package org.sparkcorporation.lims.order.api;

import java.util.regex.Pattern;

import jakarta.persistence.Embeddable;

/**
 * Typed business-key registration number — file-level daily sequence in the form {@code
 * LF-yyMMdd-NNNN}. Generated by {@code DefaultLabFileRegistrationGenerator} from the
 * UPSERT-with-RETURNING file counter.
 *
 * <p>Annotated {@code @Embeddable} so it can be embedded into the {@code LabFile} aggregate via
 * {@code @Embedded} + {@code @AttributeOverride(name = "value", column = ...)}.
 */
@Embeddable
public record LabFileRegistrationNumber(String value) {

    private static final Pattern FORMAT = Pattern.compile("^LF-\\d{6}-\\d{4}$");

    public LabFileRegistrationNumber {
        if (value == null || !FORMAT.matcher(value).matches()) {
            throw new IllegalArgumentException("invalid registration number: " + value);
        }
    }
}
